mapper.select:
WITH col_meta AS ( SELECT a.DM_ID, a.OBJ_NM, a.ATTR_NM, a.ATTR_NM_KR, d.DOMAIN_ID, d.DOMAIN_NM, d.DOMAIN_CLSF_NM FROM TB_DATA_MODEL_ATTR a LEFT JOIN TB_TERMS t ON t.TERMS_NM = a.ATTR_NM_KR LEFT JOIN TB_DOMAIN d ON d.DOMAIN_NM = t.DOMAIN_NM WHERE a.DM_ID = #{dmId} AND a.USE_YN = 'Y' AND a.OBJ_NM ILIKE '%' || #{objNm} || '%' AND a.ATTR_NM ILIKE '%' || #{attrNm} || '%'
AND d.DOMAIN_CLSF_NM = #{domainClsfNm}
), col_default_dom AS ( SELECT cm.DM_ID, cm.OBJ_NM, cm.ATTR_NM, cm.DOMAIN_ID, dr.DOMAIN_RULE_ID AS DEFAULT_DR_ID, dr.RULE_NM AS DEFAULT_RULE_NM, dr.RULE_TYPE AS DEFAULT_RULE_TYPE, dr.RULE_PARAMS AS DEFAULT_RULE_PARAMS, dr.SORT_ORD AS DEFAULT_SORT_ORD FROM col_meta cm LEFT JOIN LATERAL ( SELECT * FROM TB_DOMAIN_RULE WHERE DOMAIN_ID = cm.DOMAIN_ID AND USE_YN = 'Y' ORDER BY SORT_ORD LIMIT 1 ) dr ON true ) SELECT cm.DM_ID AS "dmId", cm.OBJ_NM AS "objNm", cm.ATTR_NM AS "attrNm", COALESCE(cm.ATTR_NM_KR, '') AS "attrNmKr", COALESCE(cm.DOMAIN_NM, '') AS "domainNm", COALESCE(cm.DOMAIN_CLSF_NM,'') AS "domainClsfNm", cr.DOMAIN_RULE_ID AS "domainRuleId", cr.CUSTOM_RULE_ID AS "customRuleId", COALESCE(cr.EXCLUDE_YN, 'N') AS "excludeYn", CASE WHEN cr.EXCLUDE_YN = 'Y' THEN NULL WHEN cr.CUSTOM_RULE_ID IS NOT NULL THEN ur.RULE_NM WHEN cr.DOMAIN_RULE_ID IS NOT NULL THEN udr.RULE_NM ELSE cd.DEFAULT_RULE_NM END AS "effectiveRuleNm", CASE WHEN cr.EXCLUDE_YN = 'Y' THEN NULL WHEN cr.CUSTOM_RULE_ID IS NOT NULL THEN ur.RULE_TYPE WHEN cr.DOMAIN_RULE_ID IS NOT NULL THEN udr.RULE_TYPE ELSE cd.DEFAULT_RULE_TYPE END AS "effectiveRuleType", CASE WHEN cr.EXCLUDE_YN = 'Y' THEN 'EXCLUDED' WHEN cr.CUSTOM_RULE_ID IS NOT NULL THEN 'CUSTOM' WHEN cr.DOMAIN_RULE_ID IS NOT NULL THEN 'DOMAIN' WHEN cd.DEFAULT_RULE_NM IS NOT NULL THEN 'DEFAULT' ELSE 'NONE' END AS "effectiveSource", -- 직전 값 진단 pr.TOTAL_CNT AS "profTotal", pr.NULL_CNT AS "profNull", pr.DISTINCT_CNT AS "profDistinct", pr.MIN_VAL AS "profMin", pr.MAX_VAL AS "profMax", pr.MIN_LEN AS "profMinLen", pr.MAX_LEN AS "profMaxLen", pr.UPDATED_DT AS "profUpdatedDt", -- 직전 룰 진단 적합률 (max diag_dt 의 RULE_RESULT) lr.VIOLATION_CNT AS "ruleViolation", lr.TOTAL_CNT AS "ruleTotal", lr.VIOLATION_RATE AS "ruleViolationRate", (CASE WHEN lr.VIOLATION_RATE IS NULL THEN NULL ELSE 100.0 - lr.VIOLATION_RATE END) AS "ruleConformRate" FROM col_meta cm LEFT JOIN col_default_dom cd ON cd.DM_ID = cm.DM_ID AND cd.OBJ_NM = cm.OBJ_NM AND cd.ATTR_NM = cm.ATTR_NM LEFT JOIN TB_QUAL_COL_RULE cr ON cr.DM_ID = cm.DM_ID AND cr.OBJ_NM = cm.OBJ_NM AND cr.ATTR_NM = cm.ATTR_NM LEFT JOIN TB_QUAL_RULE ur ON ur.RULE_ID = cr.CUSTOM_RULE_ID LEFT JOIN TB_DOMAIN_RULE udr ON udr.DOMAIN_RULE_ID = cr.DOMAIN_RULE_ID LEFT JOIN TB_QUAL_PROFILE_RESULT pr ON pr.DM_ID = cm.DM_ID AND pr.OBJ_NM = cm.OBJ_NM AND pr.ATTR_NM = cm.ATTR_NM LEFT JOIN LATERAL ( SELECT rr.VIOLATION_CNT, rr.TOTAL_CNT, rr.VIOLATION_RATE FROM TB_QUAL_RULE_RESULT rr JOIN TB_QUAL_DIAG_HISTORY dh ON dh.DIAG_ID = rr.DIAG_ID WHERE rr.OBJ_NM = cm.OBJ_NM AND rr.ATTR_NM = cm.ATTR_NM AND dh.DM_ID = cm.DM_ID AND dh.STATUS = 'DONE' ORDER BY dh.DIAG_DT DESC LIMIT 1 ) lr ON true
AND (lr.VIOLATION_RATE IS NULL OR (100.0 - lr.VIOLATION_RATE) >= #{rateMin})
AND (lr.VIOLATION_RATE IS NULL OR (100.0 - lr.VIOLATION_RATE) <= #{rateMax})
ORDER BY cm.OBJ_NM, cm.ATTR_NM
